package com.barbershop.app;
import android.content.*;
import android.net.Uri;
import android.provider.DocumentsContract;
import android.security.keystore.*;
import android.util.*;
import org.json.JSONObject;
import java.io.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/** Device-encrypted ledger; an AtomicFile recovery copy precedes any document-provider write. */
final class LocalStore {
 static final class AuthenticationException extends IOException{AuthenticationException(String message){super(message);}}
 private final Context context;private final File dir;private final String alias;
 private JSONObject meta;private boolean unlocked;private String warning="";
 LocalStore(Context c)throws Exception{this(c,new File(c.getFilesDir(),"ledger"),"qiansiwanlv-vault-v1");}
 private static boolean existsAtomic(File file){return file.exists()||new File(file.getPath()+".bak").exists();}
 LocalStore(Context c,File d,String a)throws Exception{context=c;dir=d;alias=a;if(!dir.exists()&&!dir.mkdirs())throw new IOException("无法创建本地目录");File auth=new File(dir,"account.enc");meta=existsAtomic(auth)?new JSONObject(new String(decrypt(readAtomic(auth)),"UTF-8")):new JSONObject();unlocked=configured()&&meta.optBoolean("autoLogin",false);}
 private SecretKey key()throws Exception{KeyStore s=KeyStore.getInstance("AndroidKeyStore");s.load(null);if(s.containsAlias(alias))return (SecretKey)s.getKey(alias,null);KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());return g.generateKey();}
 byte[] encrypt(byte[] v)throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] iv=c.getIV();out.write(iv.length);out.write(iv);out.write(c.doFinal(v));return out.toByteArray();}
 byte[] decrypt(byte[] v)throws Exception{if(v.length<30||v[0]!=12)throw new IOException("本地文件不完整，请保留文件");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,java.util.Arrays.copyOfRange(v,1,13)));return c.doFinal(v,13,v.length-13);}
 private static byte[] read(InputStream input)throws IOException{if(input==null)throw new IOException("文件无法读取");try(InputStream in=input;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>50000000)throw new IOException("账本文件过大");}return out.toByteArray();}}
 private static byte[] readAtomic(File f)throws IOException{return read(new AtomicFile(f).openRead());}
 private static void writeAtomic(File f,byte[] b)throws IOException{AtomicFile a=new AtomicFile(f);FileOutputStream out=null;try{out=a.startWrite();out.write(b);a.finishWrite(out);}catch(IOException e){if(out!=null)a.failWrite(out);throw e;}}
 private void saveMeta()throws Exception{writeAtomic(new File(dir,"account.enc"),encrypt(meta.toString().getBytes("UTF-8")));}
 private boolean configured(){return meta.has("hash")&&(existsAtomic(new File(dir,"vault.enc"))||!meta.optString("document","").isEmpty());}
 JSONObject info()throws Exception{return new JSONObject().put("configured",configured()).put("unlocked",unlocked).put("username",meta.optString("username","")).put("autoLogin",meta.optBoolean("autoLogin",false));}
 void requireUnlocked()throws IOException{if(!unlocked)throw new IOException("请先解锁本地账本");}
 void setAutoLogin(boolean enabled)throws Exception{requireUnlocked();JSONObject previous=new JSONObject(meta.toString());try{meta.put("autoLogin",enabled);saveMeta();}catch(Exception e){meta=previous;throw e;}}
 void lock()throws Exception{setAutoLogin(false);unlocked=false;}
 private static String verifier(String p,String salt)throws Exception{PBEKeySpec s=new PBEKeySpec(p.toCharArray(),Base64.decode(salt,Base64.NO_WRAP),120000,256);try{return Base64.encodeToString(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1").generateSecret(s).getEncoded(),Base64.NO_WRAP);}finally{s.clearPassword();}}
 void authenticated(String u,String p,String cookie,String owner)throws Exception{if(meta.has("storeId")&&!meta.getString("storeId").equals(owner))throw new IOException("云端账号与本地门店不一致，原账本保留");byte[] salt=new byte[32];new SecureRandom().nextBytes(salt);String s=Base64.encodeToString(salt,Base64.NO_WRAP);JSONObject previous=new JSONObject(meta.toString());try{meta.put("username",u).put("salt",s).put("hash",verifier(p,s)).put("cookie",cookie).put("storeId",owner).put("attempts",0);saveMeta();}catch(Exception e){meta=previous;throw e;}unlocked=true;}
 void unlock(String u,String p)throws Exception{long now=System.currentTimeMillis(),start=meta.optLong("attemptStart",0);int attempts=now-start>=900000?0:meta.optInt("attempts",0);if(attempts>=10)throw new AuthenticationException("本地密码尝试过多，请15分钟后重试");boolean ok=meta.optString("username").equals(u)&&meta.has("salt")&&MessageDigest.isEqual(verifier(p,meta.optString("salt")).getBytes("UTF-8"),meta.optString("hash").getBytes("UTF-8"));meta.put("attemptStart",now-start>=900000?now:start).put("attempts",ok?0:attempts+1);saveMeta();if(!ok)throw new AuthenticationException("账号或密码不正确");unlocked=true;}
 String cookie(){return meta.optString("cookie","");}String owner(){return meta.optString("storeId","");}
 private JSONObject envelope(byte[] bytes)throws Exception{JSONObject result=new JSONObject(new String(decrypt(bytes),"UTF-8"));JSONObject vault=result.getJSONObject("vault");if(vault.getInt("format")!=1)throw new IOException("本地账本格式不正确");if(!owner().equals(vault.getJSONObject("base").getString("storeId")))throw new IOException("本地账本与账号不一致");return result;}
 JSONObject readVault()throws Exception{requireUnlocked();File file=new File(dir,"vault.enc");JSONObject internal=null;Exception failure=null;try{internal=envelope(readAtomic(file));}catch(Exception e){failure=e;}String document=meta.optString("document","");if(!document.isEmpty())try{JSONObject external=envelope(read(context.getContentResolver().openInputStream(Uri.parse(document))));if(internal==null||external.getLong("generation")>internal.getLong("generation")){writeAtomic(file,encrypt(external.toString().getBytes("UTF-8")));internal=external;warning="已从指定目录恢复最新账本。";}else if(external.getLong("generation")<internal.getLong("generation"))warning="指定目录副本较旧，已使用设备内最新恢复副本。";}catch(Exception e){warning="指定目录暂时不可用，已使用设备内恢复副本，可继续记账。";if(failure==null)failure=e;}if(internal==null)throw new IOException("本地账本无法读取，请保留文件，不要卸载应用",failure);return internal.getJSONObject("vault");}
 JSONObject writeVault(JSONObject vault)throws Exception{requireUnlocked();if(vault.getInt("format")!=1||!owner().equals(vault.getJSONObject("base").getString("storeId")))throw new IOException("禁止写入其他门店账本");File file=new File(dir,"vault.enc");long generation=file.exists()?envelope(readAtomic(file)).getLong("generation")+1:1;byte[] bytes=encrypt(new JSONObject().put("generation",generation).put("vault",vault).toString().getBytes("UTF-8"));if(bytes.length>48000000)throw new IOException("账本容量已达限制，请先同步并联系维护人员");writeAtomic(file,bytes);String document=meta.optString("document","");if(!document.isEmpty())try{writeDocument(Uri.parse(document),bytes);warning="";}catch(Exception e){warning="已保存到设备内恢复副本，指定目录写入失败，请重新选择目录。";}return new JSONObject().put("storage",storage());}
 private void writeDocument(Uri uri,byte[] bytes)throws Exception{try(OutputStream out=context.getContentResolver().openOutputStream(uri,"rwt")){if(out==null)throw new IOException("目录不可写");out.write(bytes);}byte[] saved=read(context.getContentResolver().openInputStream(uri));if(!MessageDigest.isEqual(bytes,saved))throw new IOException("文件写入核对失败");envelope(saved);}
 void changeDirectory(Uri tree,int flags)throws Exception{requireUnlocked();readVault();context.getContentResolver().takePersistableUriPermission(tree,flags&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));Uri parent=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));Uri document=DocumentsContract.createDocument(context.getContentResolver(),parent,"application/octet-stream","千丝万缕账本-"+java.util.UUID.randomUUID().toString().substring(0,8)+".qsledger");if(document==null)throw new IOException("无法创建账本文件");writeDocument(document,readAtomic(new File(dir,"vault.enc")));JSONObject previous=new JSONObject(meta.toString());try{meta.put("document",document.toString()).put("tree",tree.toString());saveMeta();warning="";}catch(Exception e){meta=previous;throw e;}}
 void defaultDirectory()throws Exception{requireUnlocked();readVault();JSONObject previous=new JSONObject(meta.toString());try{meta.remove("document");meta.remove("tree");saveMeta();warning="";}catch(Exception e){meta=previous;throw e;}}
 JSONObject storage()throws Exception{String document=meta.optString("document","");return new JSONObject().put("path",document.isEmpty()?new File(dir,"vault.enc").getAbsolutePath():document).put("selected",!document.isEmpty()).put("fallbackPath",new File(dir,"vault.enc").getAbsolutePath()).put("warning",warning).put("cloud","https://qiansiwanlv-admin.qiansiwanlv-d64678.workers.dev");}
}

